public interface PricingRule {
    BigDecimal price(Trade t);                       // abstract: each rule must implement

    default BigDecimal priceWithFee(Trade t) {       // default: shared behaviour, can be overridden
        return price(t).add(fee(t));
    }
    private BigDecimal fee(Trade t) {                // private helper (Java 9+)
        return BigDecimal.ONE;
    }
    static PricingRule flat(BigDecimal p) {          // static factory
        return t -> p;
    }
}

public class ReportService {
    private final Exporter exporter;                  // has-a: any implementation
    public ReportService(Exporter exporter) {         // injected, e.g. by Spring
        this.exporter = exporter;
    }
    public byte[] run(Report r) { return exporter.export(r); }
}
